<?php require_once __DIR__.'/../app/layout.php';$type=($_GET['type']??'member')==='admin'?'admin':'member';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$type=($_POST['type']??'member')==='admin'?'admin':'member';$email=strtolower(trim($_POST['email']??''));$table=$type==='admin'?'admins':'members';$s=$pdo->prepare("SELECT email FROM {$table} WHERE email=?".($type==='admin'?' AND is_active=1':' AND status="active"'));$s->execute([$email]);if($s->fetch()){ $token=bin2hex(random_bytes(32));$pdo->prepare('INSERT INTO password_resets (account_type,email,token_hash,expires_at) VALUES (?,?,?,DATE_ADD(NOW(),INTERVAL 30 MINUTE))')->execute([$type,$email,hash('sha256',$token)]);$url=rtrim(env('APP_URL','https://tssmt.org'),'/').'/reset-password.php?type='.$type.'&token='.$token;org_send_mail($email,'Password reset | '.setting($pdo,'org_name','TSSMT'),'<p>Use this secure link to reset your password. It expires in 30 minutes:</p><p><a href="'.e($url).'">Reset password</a></p>');}flash('If the account exists, a password-reset link has been sent.');redirect('/forgot-password.php?type='.$type);}header_html('Forgot password');?><h1>Forgot password</h1><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="type" value="<?=e($type)?>"><label>Email address<input type="email" name="email" required></label><button>Send reset link</button></form><p><a href="<?= $type==='admin'?'/admin/login.php':'/login.php'?>">Back to login</a></p><?php footer_html();
